import{_ as e,c as l,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"地火明夷","description":"周易折中 - 地火明夷","frontmatter":{"title":"地火明夷","description":"周易折中 - 地火明夷"},"headers":[],"relativePath":"classics/zhezhong/042.md","filePath":"classics/zhezhong/042.md"}'),h={name:"classics/zhezhong/042.md"};function p(n,a,d,t,s,o){return r(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="地火明夷" tabindex="-1">地火明夷 <a class="header-anchor" href="#地火明夷" aria-label="Permalink to “地火明夷”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>〈明夷序卦〉：“晉者，進也；進必有所傷，故受之以明夷。夷者，傷也。夫進之不已，必有所傷，理自然也。明夷所以次晉也。為卦坤上離下，明入地中也。反晉成明夷，故義與晉正相反。晉者，明盛之卦，明君在上，群賢並進之時也。明夷，昏暗之卦，暗君在上，明者見傷之時也。日入於地中，明傷而昏暗也，故為明夷。”</p><p>明夷：利艱貞</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>夷，傷也。為卦下離上坤，日入地中，明而見傷之象，故為明夷。又其上六為暗之主，六五近之，故佔者利於艱難以守正而自晦其明也。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>君子當明夷之時，利在知艱難而不失其貞正也。在昏暗艱難之時而能不失其正，所以為明君子也。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎逹曰 ：時雖至暗，不可隨世傾邪，故宜艱難堅固守其貞正之德。</p></li><li><p>李氏舜臣曰 ：易卦諸爻，噬嗑之九四、大畜之九三曰“利艱貞”，未有一卦全體以利艱貞為義者。此蓋睹君子之明傷為可懼，而危辭以戒之，其時可知也。</p></li><li><p>胡氏炳文曰 ：以二體則離明也，傷之者坤；以六爻則初至五皆明也，傷之者上。上為暗主，而五近之，故本義從彖傳以利艱貞為五。</p></li></ul><p>象曰：明入地中，明夷；君子以蒞眾用晦而明</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>明所以照，君子無所不照。然用明之過，則傷於察，太察則盡事而無含弘之度。故君子觀明入地中之象，於蒞眾也，不極其明察而用晦，然後能容物和眾，眾親而安。是用晦乃所以為明也。若自任其明，無所不察，則己不勝其忿疾，而無寛厚含容之德，人情睽疑而不安，失蒞眾之道，適所以為不明也。古之聖人設前旒、屏樹者，不欲明之盡乎隱也。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎達曰：冕旒垂目，黈纊塞耳，無為清靜，民化不欺。若運其聰明顯其智慧，民即逃其密網，奸詐愈生。豈非藏明用晦，反得其明也？</p></li><li><p>張子曰：不任察而不失其治也。</p></li><li><p>林氏希元曰：用晦而明，不是以晦為明，亦不是晦其明。蓋雖明而用晦，雖用晦而明也。用晦而明，只是不盡用其明。蓋盡用其明，則傷於太察而無含弘之道。惟明而用晦，則既不汶汶而暗，亦不察察而明。雖無所不照，而有不盡照者，此古先帝王所以蒞眾之術也。</p></li><li><p>何氏楷曰：晦其明謂藏明於晦，晦而明謂生明於晦，意實相發。</p></li></ul><p>彖曰：明入地中，明夷</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>以卦象釋卦名。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li>孔氏穎逹曰 ：此就二象以釋卦名，此及晉卦皆彖象同辭也。</li></ul><p>內文明而外柔順，以蒙大難，文王以之</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>以卦德釋卦義。蒙大難，謂遭紂之亂而見囚也。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>明入於地，其明滅也，故為明夷。內卦離，離者文明之象；外卦坤衝，者柔順之象。為人內有文明之德，而外能柔順也。昔者文王如是，故曰“文王以之”。當紂之昏暗，乃明夷之時，而文王內有文明之德，外柔順以事紂，蒙犯大難而內不失其明聖，而外足以逺禍患。此文王所用之道也，故曰“文王以之”。</p><p>利艱貞，晦其明也。內難而能正其志，箕子以之</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>以六五一爻之義釋卦辭。內難，謂為紂近親，在其國內（知六五之近於上六也）。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>明夷之時，利於處艱厄而不失其貞正，謂能晦藏其明也。不晦其明，則被禍患；不守其正，則非賢明。箕子當紂之時，身處其國內，切近其難，故云“內難”。然箕子能藏晦其明而自守其正志，箕子所用之道也，故曰“箕子以之”。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>胡氏炳文曰 ：六五爻辭曰“箕子之明夷，利貞”，釋彖兼文王發之。蓋羑里演易處之甚從容，可見文王之德；佯狂受辱處之極艱難，可見箕子之志。然此一時也，文王因而發伏羲之易，箕子因而發大禹之疇。聖賢之於患難，自系斯文之㑹，蓋有天意存焉。</p></li><li><p>俞氏琰曰 ：大難謂羑里之囚也，其難闗系天下之大，民命之所寄，故曰大難。內難謂家難也，其難闗系一家之內，宗社之所寄也。箕子為紂之近親，故曰內難。</p></li></ul><p>初九：明夷于飛，垂其翼；君子於行，三日不食；有攸往，主人有言。</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>飛而垂翼，見傷之象。佔者行而不食，所如不合時義，當然不得而避也。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>初九明體，而居明夷之初，見傷之始也。九，陽明上升者也，故取飛象。昏暗在上，傷陽之明，使不得上進，是于飛而傷其翼也。翼見傷，故垂朵。凡小人之害君子，害其所以行者。“君子於行，三日不食”，君子明照，見事之微，雖始有見傷之端，未顯也，君子則能見之矣，故行去避之。“君子於行”，謂去其祿位而退藏也。“三日不食”，言困窮之極也。事未顯而處甚艱，非見幾之明不能也。夫知幾者，君子之獨見，非眾人所能識也。故明夷之始，其見傷未顯而去之，則世俗孰不疑怪？故有所往適，則主人有言也。然君子不以世俗之見怪而遲疑其行也。若俟眾人盡識，則傷己及而不能去矣。此薛方所以為明而揚雄所以不獲其去也。或曰：“傷至於垂翼，傷已明矣，何得眾人猶未識也？”曰：“初傷之始也，雲垂其翼，謂傷其所以飛爾，其事則未顯也。”君子見幾，故亟去之，世俗之人未能見也，故異而非之。如穆生之去楚，申公、白公且非之，況世俗之人乎？但譏其責小禮而不知穆生之去避胥靡之禍也。當其言曰：“不去，楚人將鉗我於市。”雖二儒者亦以為過甚之言也。又如袁閎於黨事未起之前，名德之士方鋒起而獨潛身土室，故人以為狂生，卒免黨錮之禍。所往而人有言，何足怪也。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>蘭氏廷瑞曰 ：陽剛之君子，居明夷之始，戢翼避禍，見幾先遁。</p></li><li><p>項氏安世曰 ：垂其翼，不言夷未傷也；夷於左股，言已傷也。說者以垂其翼為傷翼，非也。斂翼而下飛者，避禍之象也。</p></li><li><p>丘氏富國曰 ：初體離明，去上最遠，見傷即避，有飛而垂翼之象。君子知幾，義當速去，蓋可以不食而不可以不去，去重於食故也。</p></li><li><p>俞氏琰曰 ：居明夷之初，不敢高飛，遂垂斂其翼以向下，此見幾之明，不待難作而早避者也。夫知幾而早去，此君子獨見，主人固不識也，豈得無言？</p></li></ul><p>象曰：君子於行義，不食也</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>唯義所在，不食可也</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>君子遁藏而困窮，義當然也。唯義之當然，故安處而無悶，雖不食可也。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><p>王氏申子曰：義所不食，則于飛攸往；義所當行，亦明矣。去之可不速乎？此伯夷、太公之事。</p><p>六二：明夷，夷於左股，用拯馬壯，吉。</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>傷而未切，救之速則免矣，故其象佔如此。</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>六二以至明之才，得中正而體順，順時自處，處之至善也。雖君子自處之善，然當陰暗小人傷明之時，亦不免為其所傷。但君子自處有道，故不能深相傷害，終能違避之耳。足者所以行也，股在脛足之上，於行之用為不甚切；左又非便用者，手足之用以右為便，惟蹶張用左，蓋右立為本也。夷於左股，謂傷害其行而不甚切也。雖然，亦必自免有道。拯用壯健之馬，則獲免之速而吉也。君子為陰暗所傷，其自處有道，故其傷不甚；自拯有道，故獲免之疾。用拯之道不壯，則被傷深矣，故云馬壯則吉也。二以明居陰暗之下，所謂吉者，得免傷害而已，非謂可以有為於斯時也。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏宗傳曰 ：六二文明之主也，以六居二，柔順之至，文王以之。</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>明夷與豐卦略相似，然豐者明中之昏，明夷則昏極而不復明也。兩卦皆以上六為昏之主，六二為明之主。既為明之主，豈可不以救昏為急？故此之“夷於左股”者，與豐二之“往得疑疾”同也；此之“用拯馬壯”者，與豐之“有孚發若”同也。蓋未至於豐三之“折其右肱”，則猶有可為之理也。</p><p>象曰：六二之吉，順以則也</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>六二之得吉者，以其順處而有法則也。則謂中正之道，能順而得中正，所以處明夷之時而能保其吉也。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>項氏安世曰：明夷之下三爻，惟六二有救之之誠；上三爻，惟六五無去之之心，皆中順之臣也。</p></li><li><p>王氏申子曰：以柔順處之而不失其中正之則，昔者文王用明夷之道，其如是乎？</p></li></ul><p>九三：明夷於南狩，得其大首，不可疾貞。</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>以剛居剛，又在明體之上，而屈於至暗之下，正與上六暗主為應，故有嚮明除害，得其首惡之象。然不可以亟也，故有不可疾貞之戒。成湯起於夏臺，文王興於羑里，正合此爻之義。而小事亦有然者。</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>九三，離之上，明之極也，又處剛而進。上六，坤之上，暗之極也。至明居下而為下之上，至暗在上而處窮極之地，正相敵應，將以明去暗者也。斯義也，其湯武之事乎？南在前而明方也，狩畋而去害之事也。南狩，謂前進而除害也。當克獲其大首，大首謂暗之魁首，上六也。三與上正相應，為至明克至暗之象。不可疾貞，謂誅其元惡，舊染汙俗未能遽革，必有其漸。革之遽，則駭懼而不安。故《酒誥》雲：“惟殷之迪諸臣，惟工乃湎於酒，毋庸殺之，姑惟教之。”至於既乆，尚曰“餘風未殄”，是漸漬之俗，不可以遽革也。故曰“不可疾貞”，正之不可急也。上六雖非君位，以其居上而暗之極，故為暗之主，謂之大首。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li>胡氏炳文曰 ：二之救難可速也，三之除害不可速也，故有“不可疾貞”之戒。</li></ul><p>象曰：南狩之志，乃大得也</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>夫以下之明除上之暗，其志在去害而已。如商周之湯武，豈有意於利天下乎？得其大首，是能去害而大得其志矣。志苟不然，乃悖亂之事也。</p><p>六四：入於左腹，獲明夷之心，於出門庭。</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>此爻之義未詳，竊疑左腹者幽隱之處，獲明夷之心於出門庭者，得意於遠去之義。言筮而得此者，其自處當如是也。蓋離體為至明之德，坤體為至暗之地，下三爻明在暗外，故隨其遠近髙下而處之不同。六四以柔正居暗地而尚淺，故猶可以得意於遠去。五以柔中居暗地而已迫，故為內難正志以晦其明之象。上則極乎暗矣，故為自傷其明以至於暗，而又足以傷人之明。蓋下五爻皆為君子，獨上一爻為暗君也。</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>六四以陰居陰，而在陰柔之體，處近君之位，是陰邪小人居高位以柔邪順於君者也。六五明夷之君位，傷明之主也。四以柔邪順從之，以固其交。夫小人之事君，未有由顯明以道合者也，必以隱僻之道自結於上。右當用，故為明顯之所；左不當用，故為隱僻之所。人之手足皆以右為用，世謂僻所為僻左，是左者隱僻之所也。四由隱僻之道深入其君，故云“入於左腹”，“入腹”謂其交深也。其交之深，故得其心。凡奸邪之見信於其君，皆由奪其心也。不奪其心，能無悟乎？於出門庭，既信之於心，而後行之於外也。邪臣之事暗君，必先蠱其心，而後能行於外。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>楊氏時曰 ：腹，坤象也，坤體之下，故曰左腹（尊右故也）。獲明夷之心，所謂求仁而得仁也。此君子之明夷也。</p></li><li><p>朱子語類雲 ：明夷下三爻皆說明夷是明而見傷者，六四說者卻以為奸邪之臣先蠱惑其君心而後肆行於外。下三爻皆說明夷是好底，何獨此爻卻作不好說？以意觀之，六四居暗地尚淺，猶可以得意而遠去，故雖入於幽隱之處，猶能獲明夷之心於出門庭也。上六不明晦，則是合下已是不明。</p></li><li><p>胡氏炳文曰 ：初二三在暗外，至四則將入暗中，然比之六五，則四尚淺也，猶可得意於遠去。獲明夷之心者，微子之自靖於出門庭者，君子之行遁也。</p></li></ul><p>象曰：入於左腹，獲心意也</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>入於左腹，謂以邪僻之道入於君而得其心意也。得其心，所以終不悟也。</p><p>六五：箕子之明夷，利貞</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>居至暗之地，近至暗之君，而能正其志，箕子之象也。貞之至也，利貞以戒佔者。</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>五為君位，乃常也。然《易》之取義，變動隨時。上六處坤之上，而明夷之極，陰暗傷明之極者也。五切近之，聖人因以五為切近至暗之人，以見處之之義，故不專以君位言。上六陰暗傷明之極，故以為明夷之主。五切近傷明之主，若顯其明，則見傷害必矣。故當如箕子之自晦藏，則可以免於難。箕子，商之舊臣而同姓之親，可謂切近於紂矣。若不自晦其明，被禍可必也。故佯狂為奴，以免於害。雖晦藏其明，而內守其正，所謂內難而能正其志，所以謂之仁與明也。若箕子可謂貞矣。以五陰柔，故為之戒雲“利貞”，謂宜如箕子之貞固也。若以君道言，義亦如是。人君有當含晦之時，亦外晦其明而內正其志也。</p><p>象曰：箕子之貞，明不可息也</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>箕子晦藏不失其貞固，雖遭患難，其明自存，不可滅息也。若逼禍患遂失其所守，則是亡其明，乃滅息也。古之人如揚雄者是也。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><p>蘇氏軾曰：六五之於上六，正之則勢不敵，救之則力不能，去之則義不可，此最難處者也。如箕子而後可。箕子之處於此，身可辱也，而明不可息也。</p><p>上六：不明晦，初登於天，後入於地</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>以陰居坤之極，不明其德，以至於晦。始則處高位以傷人之明，終必至於自傷而墜厥命。故其象如此，而佔亦在其中矣。</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>上居卦之終，為夷明之主，又為明夷之極。上至髙之地，明在至髙，本當遠照，明既夷傷，故不明而反昏晦也。本居於高明，當及遠，初登於天也，乃夷傷其明而昏暗，後入於地也。上明夷之終，又坤陰之終，明傷之極者也。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li>蘇氏軾曰 ：六爻皆晦也，而所以晦者不同。自五以下，明而晦者也；若上六，不明而晦者也。故曰“不明晦”。</li></ul><p>蘇氏軾曰 ：六爻皆晦也，而所以晦者不同。自五以下，明而晦者也；若上六，不明而晦者也。故曰“不明晦”。</p><ul><li>胡氏炳文曰 ：下三爻以“明夷”為句首，四、五“明夷”之辭在句中，上六不曰“明夷”而曰“不明晦”，蓋惟上六不明而晦，所以五爻之明皆為其所夷也。</li></ul><p>胡氏炳文曰 ：下三爻以“明夷”為句首，四、五“明夷”之辭在句中，上六不曰“明夷”而曰“不明晦”，蓋惟上六不明而晦，所以五爻之明皆為其所夷也。</p><p>象曰：初登於天，照四國也；後入於地，失則也</p><h3 id="本義-11" tabindex="-1">本義 <a class="header-anchor" href="#本義-11" aria-label="Permalink to “本義”">​</a></h3><p>照四國以位言</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>初登於天，居高而明，則當照及四方也。乃被傷而昏暗，是後入於地，失明之道也。失則，失其道也。</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><p>胡氏炳文曰：則者，不可逾之理。失則，所以為紂；順則，所以為文王。</p><p>總論</p><p>蘇氏軾曰 ：力能救則救之，六二之用拯是也；力能正則正之，九三之南狩是也。既不能救，又不能正，君子不敢辭其辱以私便其身，六五之箕子是也。君子居明夷之世，有責必有以塞之，無責必有以全其身而不失其正。初九、六四無責於斯世，故近者則入腹獲心於出門庭，而遠者則行不及食也。</p>',109)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
